CREATE OR REPLACE FUNCTION private.lock_hangout(target uuid)
 RETURNS hangouts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.hangouts;
begin
  select * into h from public.hangouts where id=target for update;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  perform 1 from private.hangout_feature_gate where singleton for share;
  perform private.safety_lock_hangout_evidence(auth.uid(),h.university_id);
  if h.university_id is distinct from private.ready_campus()
    or exists(select 1 from private.hangout_disables where hangout_id=target) then
    raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  update public.hangouts set updated_at=updated_at where id=target;
  return h;
end; $function$

CREATE OR REPLACE FUNCTION private.sync_confirmed_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare campus uuid;
begin
  if new.email_confirmed_at is not null and new.email ~ '^[^@[:space:]]+@[^@[:space:]]+$' then
    select id into campus from public.universities
    where slug = 'unc-chapel-hill' and active
      and lower(split_part(new.email, '@', 2)) = any(allowed_email_domains);
  end if;
  if campus is null then
    delete from public.university_memberships where user_id = new.id;
  else
    insert into public.university_memberships(user_id, university_id, verified_at, verification_email)
    values (new.id, campus, new.email_confirmed_at, lower(new.email))
    on conflict (user_id) do update set university_id = excluded.university_id,
      verified_at = excluded.verified_at, verification_email = excluded.verification_email;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.provision_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.accounts(id) values (new.id);
  insert into public.profiles(user_id) values (new.id);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_profile_photos()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare path text;
begin
 -- A KEY SHARE lock lasts through commit. A concurrent delete either waits,
 -- fails serialization at stronger isolation, or deadlocks and aborts safely.
 for path in select unnest(array_remove(array_prepend(new.primary_photo_path,new.additional_photo_paths),null)) order by 1 loop
   perform 1 from storage.objects o where o.bucket_id='profile-photos' and o.name=path
     and o.owner_id=new.user_id::text and split_part(o.name,'/',1)=new.user_id::text for key share;
   if not found then raise exception 'Photos must be existing owned private objects' using errcode='23514'; end if;
 end loop;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_profile_photo_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare profile public.profiles;
begin
 if old.bucket_id='profile-photos' then
   -- RLS NOT EXISTS alone has a stale statement snapshot race. Lock the profile
   -- and examine the returned current tuple, not a pre-lock snapshot. A newer
   -- tuple at REPEATABLE READ aborts. Lock inversion may abort, never orphan.
   select * into profile from public.profiles where user_id::text=old.owner_id for update;
   if found and (profile.primary_photo_path=old.name or old.name=any(profile.additional_photo_paths)) then
     raise exception 'Detach a profile photo before deleting it' using errcode='23514';
   end if;
 end if;
 return old;
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_hangout_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.host_id is distinct from old.host_id or new.university_id is distinct from old.university_id
    or (old.status = 'cancelled' and new is distinct from old
      and (new.revision <> old.revision + 1
        or (to_jsonb(new) - 'revision') is distinct from (to_jsonb(old) - 'revision')))
    or (new.revision <> old.revision + 1 and new is distinct from old) then
    raise exception 'Immutable Hangout ownership or lifecycle' using errcode = '23514';
  end if;
  if (new.starts_at is distinct from old.starts_at or new.ends_at is distinct from old.ends_at)
    and clock_timestamp() >= coalesce(old.ends_at, old.starts_at + interval '2 hours') then
    raise exception 'Hangout schedule is closed' using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_hangout(p_request_id uuid, p_title text, p_starts_at timestamp with time zone, p_public_place text, p_public_latitude double precision, p_public_longitude double precision, p_description text DEFAULT NULL::text, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_campus_zone text DEFAULT NULL::text, p_private_instructions text DEFAULT NULL::text, p_visibility text DEFAULT 'campus'::text, p_location_precision text DEFAULT 'approximate_area'::text, p_eligibility jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence record; campus uuid; result uuid; existing_id uuid; existing_fingerprint text; fingerprint text; normalized_private text;
begin
 select * into evidence from private.pilot_lock_ordinary_lifecycle('create_hangout',null,p_request_id);
 campus:=evidence.campus_id;
 existing_id:=evidence.prior_hangout_id; existing_fingerprint:=evidence.prior_payload_fingerprint;
 perform private.pilot_require_ordinary_lifecycle('create_hangout',existing_id);
 perform private.validate_hangout_input(p_title,p_starts_at,p_public_place,p_public_latitude,p_public_longitude,p_description,p_ends_at,p_campus_zone,p_visibility,p_location_precision,p_eligibility);
 perform private.validate_hangout_instructions(p_private_instructions);
 if p_request_id is null then raise exception 'Invalid Hangout input' using errcode='22023'; end if;
 normalized_private=nullif(private.profile_trim(p_private_instructions),'');
 fingerprint=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(jsonb_build_array(private.profile_trim(p_title),extract(epoch from p_starts_at),
   private.profile_trim(p_public_place),p_public_latitude,p_public_longitude,
   nullif(private.profile_trim(p_description),''),extract(epoch from p_ends_at),
   nullif(private.profile_trim(p_campus_zone),''),normalized_private,
   p_visibility,p_location_precision,p_eligibility)::text,'UTF8')),'hex');
 if existing_id is not null then
   -- The current gate/readiness/campus and row access must still hold. Never
   -- replay private content, even when the original write had it.
   if not private.can_read_hangout(existing_id) then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
   if existing_fingerprint<>fingerprint then raise exception 'Creation request conflict' using errcode='23505'; end if;
   perform private.pilot_require_ordinary_lifecycle('create_hangout',existing_id);
   return existing_id;
 end if;
 if p_starts_at<clock_timestamp() or p_starts_at>clock_timestamp()+interval '366 days' then
   raise exception 'Invalid Hangout input' using errcode='22023';
 end if;
 perform private.pilot_require_ordinary_lifecycle('create_hangout',null);
 insert into public.hangouts(university_id,host_id,title,starts_at,public_place,public_latitude,public_longitude,description,ends_at,campus_zone)
 values(campus,auth.uid(),private.profile_trim(p_title),p_starts_at,private.profile_trim(p_public_place),p_public_latitude,p_public_longitude,nullif(private.profile_trim(p_description),''),p_ends_at,nullif(private.profile_trim(p_campus_zone),'')) returning id into result;
 insert into public.hangout_participants(hangout_id,account_id,state) values(result,auth.uid(),'joined');
 if normalized_private is not null then
   insert into public.hangout_private_locations(hangout_id,instructions) values(result,normalized_private);
 end if;
 insert into private.hangout_create_requests(host_id,request_id,hangout_id,payload_fingerprint) values(auth.uid(),p_request_id,result,fingerprint);
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_hangout(p_hangout_id uuid, p_expected_revision bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence record; h public.hangouts; next_revision bigint;
begin
 select * into evidence from private.pilot_lock_ordinary_lifecycle('cancel_hangout',p_hangout_id);
 h:=evidence.source_row;
 perform private.pilot_require_ordinary_lifecycle('cancel_hangout',p_hangout_id);
 if h.host_id<>auth.uid() or h.status<>'published' then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.check_hangout_revision(h,p_expected_revision);
 perform private.pilot_require_ordinary_lifecycle('cancel_hangout',p_hangout_id);
 update public.hangouts set status='cancelled',joining_state='closed',revision=revision+1,updated_at=clock_timestamp() where id=h.id returning revision into next_revision;
 perform private.notification_emit_hangout(gen_random_uuid(),h.id,auth.uid(),'hangout_cancelled');
 return next_revision;
end; $function$

CREATE OR REPLACE FUNCTION public.leave_hangout(p_hangout_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence record; h public.hangouts; was_cohost boolean;
begin
 select * into evidence from private.pilot_lock_ordinary_lifecycle('leave_hangout',p_hangout_id);
 h:=evidence.source_row;
 perform private.pilot_require_ordinary_lifecycle('leave_hangout',p_hangout_id);
 if h.host_id=auth.uid() then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 was_cohost:=exists(select 1 from private.hangout_cohosts c where c.hangout_id=h.id and c.account_id=auth.uid());
 perform private.pilot_require_ordinary_lifecycle('leave_hangout',p_hangout_id);
 perform private.safety_record_joined_overlap(h.id,auth.uid());
 update public.hangout_participants set state='left',left_at=clock_timestamp(),updated_at=clock_timestamp()
 where hangout_id=h.id and account_id=auth.uid() and state='joined';
 if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if was_cohost then
   update public.hangouts set revision=revision+1,
     updated_at=case when status='cancelled' then updated_at else clock_timestamp() end
     where id=h.id;
 end if;
 perform private.notification_emit_hangout(gen_random_uuid(),h.id,auth.uid(),'hangout_left');
end; $function$

CREATE OR REPLACE FUNCTION private.chat_lock_evidence(p_hangout_id uuid, p_actor uuid, p_campus uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare photo_path text;
begin
  perform 1 from private.hangout_feature_gate where singleton for share;
  perform 1 from private.hangout_chat_feature_gate where singleton for share;
  perform 1 from public.accounts where id = p_actor for share;
  perform 1 from auth.users where id = p_actor for share;
  perform 1 from public.university_memberships where user_id = p_actor for share;
  perform 1 from public.universities where id = p_campus for share;
  select primary_photo_path into photo_path from public.profiles where user_id = p_actor for share;
  perform 1 from storage.objects where bucket_id = 'profile-photos'
    and name = photo_path and owner_id = p_actor::text for share;
  perform 1 from public.hangout_participants
    where hangout_id = p_hangout_id and account_id = p_actor for share;
end;
$function$

CREATE OR REPLACE FUNCTION private.chat_require(p_hangout_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_hangout_id is null or not coalesce(private.chat_authorized(p_hangout_id), false) then
    raise exception 'Hangout chat unavailable' using errcode = '42501';
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_hangout_message(p_hangout_id uuid, p_request_id uuid, p_body text)
 RETURNS TABLE(message_id uuid, sequence bigint, body text, created_at timestamp with time zone, mine boolean, author_id uuid, author_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := auth.uid(); h public.hangouts; normalized text;
  fingerprint text; old_message uuid; old_fingerprint text; conversation uuid;
  new_sequence bigint; new_message uuid;
begin
  perform private.social_hangout_mutation_lock();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Hangout chat unavailable' using errcode = '42501';
  end if;
  -- Serialize with join, leave, remove and cancel using their existing parent
  -- lock. This also makes two sends of the same key strictly ordered.
  h := private.lock_hangout(p_hangout_id);
  perform private.chat_lock_evidence(h.id, actor, h.university_id);
  -- A fresh READ COMMITTED statement after lock waits sees committed revocation.
  perform private.chat_require(h.id);
  if p_request_id is null or p_body is null then
    raise exception 'Invalid Hangout message' using errcode = '22023';
  end if;
  normalized := private.profile_trim(p_body);
  if length(normalized) not between 1 and 2000 then
    raise exception 'Invalid Hangout message' using errcode = '22023';
  end if;
  fingerprint := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(normalized, 'UTF8')), 'hex');
  select r.message_id, r.payload_fingerprint into old_message, old_fingerprint
    from private.hangout_message_requests r
    where r.hangout_id = h.id and r.author_id = actor and r.request_id = p_request_id;
  if found then
    if old_fingerprint <> fingerprint then
      raise exception 'Message request conflict' using errcode = '23505';
    end if;
    return query select m.id, m.sequence, m.body, m.created_at, true, actor, null::text
      from private.hangout_messages m where m.id = old_message;
    return;
  end if;
  insert into private.hangout_conversations(hangout_id) values (h.id)
    on conflict(hangout_id) do nothing;
  update private.hangout_conversations c set next_sequence = c.next_sequence + 1
    where c.hangout_id = h.id returning c.id, c.next_sequence - 1 into conversation, new_sequence;
  insert into private.hangout_messages(conversation_id, author_id, sequence, body)
    values (conversation, actor, new_sequence, normalized) returning id into new_message;
  insert into private.hangout_message_requests(hangout_id, author_id, request_id, message_id, payload_fingerprint)
    values (h.id, actor, p_request_id, new_message, fingerprint);
  return query select m.id, m.sequence, m.body, m.created_at, true, actor, null::text
    from private.hangout_messages m where m.id = new_message;
end;
$function$

CREATE OR REPLACE FUNCTION private.notification_emit_hangout(p_event uuid, p_hangout uuid, p_actor uuid, p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare recipient uuid; event_category text; essential boolean; kind text;
begin
 if p_code not in('hangout_edited','hangout_cancelled','hangout_joined','hangout_left','hangout_chat_message') then
  raise exception 'Invalid notification event' using errcode='22023'; end if;
 perform 1 from private.hangout_feature_gate where singleton for share;
 -- A fresh READ COMMITTED check after any source-gate lock wait.
 if not private.hangouts_enabled() then return; end if;
 if p_code='hangout_chat_message' then
  perform 1 from private.hangout_chat_feature_gate where singleton for share;
  if not exists(select 1 from private.hangout_chat_feature_gate where singleton and enabled) then return; end if;
 end if;
 perform 1 from private.notification_feature_gate where singleton for share;
 if not private.notification_enabled() then return; end if;
 essential:=p_code='hangout_cancelled';
 event_category:=case when p_code='hangout_chat_message' then 'messages'
  when p_code in('hangout_joined','hangout_left') then 'host_activity' else 'hangout_updates' end;
 kind:=case when p_code='hangout_chat_message' then 'hangout_chat' else 'hangout' end;
 for recipient in
  select p.account_id from public.hangout_participants p join public.hangouts h on h.id=p.hangout_id
  where p.hangout_id=p_hangout and p.state='joined' and p.account_id<>p_actor
   and (p_code not in('hangout_joined','hangout_left') or p.account_id=h.host_id)
  order by p.account_id
 loop
  perform private.notification_lock_recipient(recipient);
  -- Fresh statement after waiting for a preference write.
  if private.notification_enabled() and (essential or not exists(
    select 1 from private.notification_preferences pref where pref.recipient_id=recipient
      and pref.category=event_category and not pref.enabled)) then
   insert into private.notification_items(recipient_id,source_kind,source_id,target_id,event_code,actor_id)
    values(recipient,kind,p_event,p_hangout,p_code,p_actor)
    on conflict(recipient_id,source_kind,source_id,event_code) do nothing;
  end if;
 end loop;
end; $function$

CREATE OR REPLACE FUNCTION private.notification_chat_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid;
begin
 select c.hangout_id into target from private.hangout_conversations c where c.id=new.conversation_id;
 perform private.notification_emit_hangout(new.id,target,new.author_id,'hangout_chat_message');
 return new;
end; $function$

CREATE OR REPLACE FUNCTION private.safety_lock_visible_evidence(p_actor uuid, p_peer uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare subject uuid; campus uuid; photo_path text;
begin
  perform 1 from private.people_feature_gate where singleton for share;
  for subject in select id from (values(p_actor),(p_peer)) v(id) order by id loop
    perform 1 from public.accounts where id=subject for share;
    perform 1 from auth.users where id=subject for share;
    select university_id into campus from public.university_memberships
      where user_id=subject for share;
    perform 1 from public.universities where id=campus for share;
    select primary_photo_path into photo_path from public.profiles
      where user_id=subject for share;
    perform 1 from storage.objects where bucket_id='profile-photos'
      and name=photo_path and owner_id=subject::text for share;
    perform 1 from private.people_preferences where account_id=subject for share;
  end loop;
end; $function$

CREATE OR REPLACE FUNCTION private.safety_lock_hangout_evidence(p_actor uuid, p_campus uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare photo_path text;
begin
  perform 1 from public.accounts where id=p_actor for share;
  perform 1 from auth.users where id=p_actor for share;
  perform 1 from public.university_memberships where user_id=p_actor for share;
  perform 1 from public.universities where id=p_campus for share;
  select primary_photo_path into photo_path from public.profiles where user_id=p_actor for share;
  perform 1 from storage.objects where bucket_id='profile-photos'
    and name=photo_path and owner_id=p_actor::text for share;
end; $function$

CREATE OR REPLACE FUNCTION public.apply_account_moderation_action(p_report_id uuid, p_request_id uuid, p_expected_case_revision bigint, p_action text, p_reason text)
 RETURNS TABLE(case_state text, revision bigint, account_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid; r private.safety_reports%rowtype;
  c private.moderation_cases%rowtype; prior private.moderation_requests%rowtype;
  target public.accounts%rowtype; normalized_reason text; fingerprint text;
  required_role text; next_status text; campus uuid; saved_sanction uuid;
begin
  -- Stage A order: moderation advisory lock, gate, actor account and role,
  -- stored report, target account, request UUID, case, membership, writes.
  -- The target account UPDATE lock also excludes concurrent FK key-share
  -- platform-role insertion. It conflicts with student evidence SHARE locks.
  actor:=private.moderation_actor();
  normalized_reason:=private.profile_trim(p_reason);
  if p_report_id is null or p_request_id is null
    or p_expected_case_revision is null or p_expected_case_revision<0
    or p_action is null or p_action not in ('suspend','ban','reinstate')
    or normalized_reason is null or char_length(normalized_reason) not between 1 and 2000
    or not private.moderation_report_allowed(actor,p_report_id,true) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into r from private.safety_reports where id=p_report_id;
  if r.target_type<>'user' then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into target from public.accounts where id=r.target_id;
  if not found or exists(select 1 from public.platform_roles where user_id=r.target_id) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  required_role:=case when p_action='suspend' then 'moderator' else 'admin' end;
  if not exists(select 1 from public.platform_roles where user_id=actor and
    (role='admin' or (required_role='moderator' and role='moderator'))) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  fingerprint:='account:'||md5(jsonb_build_array(p_report_id,
    p_expected_case_revision,p_action,normalized_reason)::text);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,17017));
  select * into prior from private.moderation_requests
    where operator_id=actor and request_id=p_request_id;
  if found then
    if prior.fingerprint<>fingerprint then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    -- Current operator/gate/conflict/target-role checks occurred above. The
    -- replay reveals only the original minimal result, not current status.
    select s.new_status into account_status from private.account_sanctions s
      where s.operator_id=actor and s.request_id=p_request_id
        and s.report_id=p_report_id;
    if account_status is null then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    case_state:=prior.result_state; revision:=prior.result_revision;
    return next; return;
  end if;
  select * into c from private.moderation_cases
    where report_id=p_report_id for update;
  if not found or c.state<>'in_review'
    or c.revision<>p_expected_case_revision then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  next_status:=case p_action when 'suspend' then 'suspended'
    when 'ban' then 'banned' else 'active' end;
  if (p_action='suspend' and target.status<>'active')
    or (p_action='ban' and target.status not in ('active','suspended'))
    or (p_action='reinstate' and target.status not in ('suspended','banned')) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select university_id into campus from public.university_memberships
    where user_id=r.target_id for share;
  -- The account, role, case, gate, report and current membership are held
  -- through commit. Recheck after every possible lock wait.
  if not exists(select 1 from private.moderation_feature_gate where singleton and enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.platform_roles where user_id=actor and
      (role='admin' or (required_role='moderator' and role='moderator')))
    or exists(select 1 from public.platform_roles where user_id=r.target_id)
    or not exists(select 1 from public.accounts where id=r.target_id
      and status=target.status) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  insert into private.account_sanctions(report_id,subject_id,operator_id,request_id,
    action,previous_status,new_status,subject_campus_id,reason)
    values(r.id,r.target_id,actor,p_request_id,p_action,target.status,
      next_status,campus,normalized_reason) returning id into saved_sanction;
  update public.accounts set status=next_status where id=r.target_id;
  update private.moderation_cases set state='closed',revision=c.revision+1,
    note=normalized_reason,disposition='action_taken',duplicate_report_id=null,
    sanction_id=saved_sanction where report_id=r.id;
  insert into private.moderation_requests(operator_id,request_id,fingerprint,
    report_id,result_state,result_revision)
    values(actor,p_request_id,fingerprint,r.id,'closed',c.revision+1);
  insert into private.moderation_audit(operator_id,action,report_id,
    subject_target_type,subject_target_id,subject_campus_id,request_id,
    previous_state,new_state,previous_revision,new_revision,reason,sanction_id,
    previous_account_status,new_account_status)
    values(actor,p_action,r.id,'user',r.target_id,campus,p_request_id,
      c.state,'closed',c.revision,c.revision+1,normalized_reason,saved_sanction,
      target.status,next_status);
  case_state:='closed'; revision:=c.revision+1; account_status:=next_status;
  return next;
end; $function$

CREATE OR REPLACE FUNCTION private.moderation_report_allowed(p_actor uuid, p_report uuid, p_for_action boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.safety_reports%rowtype; host uuid;
begin
  select * into r from private.safety_reports where id=p_report for share;
  if not found or r.reporter_id=p_actor or r.target_id=p_actor then return false; end if;
  if r.target_type='user' then
    if p_for_action then
      -- A case writer must conflict with the account FK key-share acquired
      -- by a concurrent platform-role insertion.
      perform 1 from public.accounts where id=r.target_id for update;
    else
      -- Queue/detail need stable context, but SHARE avoids a cycle with
      -- safety block writers that lock Hangout parents before peer accounts.
      perform 1 from public.accounts where id=r.target_id for share;
    end if;
  else
    select h.host_id into host from public.hangouts h where h.id=r.target_id for share;
    if host=p_actor then return false; end if;
  end if;
  -- A fresh statement after any wait is required. A missing target is still
  -- reviewable, but a currently privileged user target is not actionable.
  if r.target_type='hangout' and exists(select 1 from public.hangouts
      where id=r.target_id and host_id=p_actor) then return false; end if;
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.join_hangout(p_hangout_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence record; h public.hangouts; participant_state text; did_join boolean;
begin
 select * into evidence from private.pilot_lock_ordinary_lifecycle('join_hangout',p_hangout_id);
 h:=evidence.source_row;
 perform private.pilot_require_ordinary_lifecycle('join_hangout',p_hangout_id);
  if h.status <> 'published' or h.joining_state <> 'open' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  if exists(select 1 from public.hangout_participants p where p.hangout_id = h.id
    and p.state = 'joined' and p.account_id <> auth.uid()
    and private.safety_pair_blocked(auth.uid(), p.account_id)) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  select state into participant_state from public.hangout_participants
    where hangout_id = h.id and account_id = auth.uid();
  if participant_state = 'removed' then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
 perform private.pilot_require_ordinary_lifecycle('join_hangout',p_hangout_id);
  if participant_state = 'joined' then return; end if;
  insert into public.hangout_participants(hangout_id, account_id, state)
    values (h.id, auth.uid(), 'joined')
    on conflict(hangout_id, account_id) do update
      set state = 'joined', joined_at = clock_timestamp(), left_at = null,
          updated_at = clock_timestamp()
      where hangout_participants.state = 'left';
  did_join := found;
  if did_join then
    perform private.safety_record_joined_overlap(h.id, auth.uid());
    perform private.record_large_hangout_join(h.id);
    perform private.notification_emit_hangout(gen_random_uuid(), h.id, auth.uid(), 'hangout_joined');
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_hangout_moderation_action(p_report_id uuid, p_request_id uuid, p_expected_case_revision bigint, p_reason text)
 RETURNS TABLE(case_state text, revision bigint, target_disabled boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; r private.safety_reports%rowtype; h public.hangouts%rowtype;
  c private.moderation_cases%rowtype; prior private.moderation_requests%rowtype;
  normalized_reason text; fingerprint text; saved_disable uuid;
begin
  -- Shared social lock precedes the parent. Stage A actor lock/gate/role
  -- precede the report. Take the Hangout parent UPDATE lock exactly once,
  -- then retry identity, case, and writes. No FOR SHARE upgrade.
  perform private.social_hangout_mutation_lock();
  actor:=private.moderation_actor();
  normalized_reason:=private.profile_trim(p_reason);
  if p_report_id is null or p_request_id is null or p_expected_case_revision is null
    or p_expected_case_revision<0 or normalized_reason is null
    or char_length(normalized_reason) not between 1 and 2000 then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into r from private.safety_reports where id=p_report_id for share;
  if not found or r.target_type<>'hangout' or r.reporter_id=actor then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  select * into h from public.hangouts where id=r.target_id for update;
  if not found or h.host_id=actor then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  -- Recheck every authority source after the parent wait. The live target
  -- stays locked through commit, so host and campus cannot change beneath us.
  if not exists(select 1 from private.moderation_feature_gate where singleton and enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.platform_roles where user_id=actor
      and role in ('moderator','admin'))
    or r.reporter_id=actor or h.host_id=actor then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  fingerprint:='hangout:'||md5(jsonb_build_array(p_report_id,
    p_expected_case_revision,normalized_reason)::text);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||p_request_id::text,17017));
  select * into prior from private.moderation_requests
    where operator_id=actor and request_id=p_request_id;
  if found then
    if prior.fingerprint<>fingerprint or prior.report_id<>p_report_id
      or not exists(select 1 from private.hangout_disables d
        where d.operator_id=actor and d.request_id=p_request_id
          and d.report_id=p_report_id and d.hangout_id=h.id) then
      raise exception 'Moderation unavailable' using errcode='42501'; end if;
    case_state:=prior.result_state; revision:=prior.result_revision;
    target_disabled:=true; return next; return;
  end if;
  select * into c from private.moderation_cases
    where report_id=p_report_id for update;
  if not found or c.state<>'in_review' or c.revision<>p_expected_case_revision
    or exists(select 1 from private.hangout_disables where hangout_id=h.id) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  insert into private.hangout_disables(report_id,hangout_id,operator_id,request_id,
    subject_campus_id,reason)
    values(r.id,h.id,actor,p_request_id,h.university_id,normalized_reason)
    returning id into saved_disable;
  update private.moderation_cases set state='closed',revision=c.revision+1,
    note=normalized_reason,disposition='action_taken',duplicate_report_id=null,
    sanction_id=null,hangout_disable_id=saved_disable where report_id=r.id;
  insert into private.moderation_requests(operator_id,request_id,fingerprint,
    report_id,result_state,result_revision)
    values(actor,p_request_id,fingerprint,r.id,'closed',c.revision+1);
  insert into private.moderation_audit(operator_id,action,report_id,
    subject_target_type,subject_target_id,subject_campus_id,request_id,
    previous_state,new_state,previous_revision,new_revision,reason,hangout_disable_id,
    previous_hangout_disabled,new_hangout_disabled)
    values(actor,'disable_hangout',r.id,'hangout',h.id,h.university_id,p_request_id,
      c.state,'closed',c.revision,c.revision+1,normalized_reason,saved_disable,false,true);
  case_state:='closed'; revision:=c.revision+1; target_disabled:=true;
  return next;
end; $function$

CREATE OR REPLACE FUNCTION private.pilot_lock_ordinary_lifecycle(p_operation text, p_hangout_id uuid, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(actor_id uuid, host_id uuid, campus_id uuid, source_row hangouts, prior_hangout_id uuid, prior_payload_fingerprint text, locked_subject_bindings jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare subjects uuid[]; subject uuid; campus uuid; photo text; object_id uuid; binding jsonb;
 memberships jsonb:='{}'::jsonb; photos jsonb:='{}'::jsonb; objects jsonb:='{}'::jsonb;
begin
 -- Social is first, including its established stronger-isolation error.
 perform private.social_hangout_mutation_lock();
 actor_id:=auth.uid();
 if actor_id is null or p_operation is null or p_operation not in ('create_hangout','edit_hangout','cancel_hangout','join_hangout','leave_hangout','set_hangout_joining')
  or (p_operation='create_hangout' and p_hangout_id is not null)
  or (p_operation<>'create_hangout' and (p_hangout_id is null or p_request_id is not null)) then
  raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.pilot_evidence_lock();
 perform 1 from private.pilot_availability where singleton for share;
 if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform 1 from private.pilot_capabilities where key='hangouts' for share;
 if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if not private.pilot_capability_enabled('hangouts') then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if p_operation='create_hangout' then
  if p_request_id is not null then
   perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor_id::text||p_request_id::text,0));
   select r.hangout_id,r.payload_fingerprint into prior_hangout_id,prior_payload_fingerprint
    from private.hangout_create_requests r where r.host_id=actor_id and r.request_id=p_request_id;
  end if;
  if prior_hangout_id is not null then
   select h.* into source_row from public.hangouts h where h.id=prior_hangout_id for update;
   if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  end if;
 else
  select h.* into source_row from public.hangouts h where h.id=p_hangout_id for update;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 end if;
 host_id:=coalesce(source_row.host_id,actor_id);
 campus_id:=source_row.university_id;
 perform 1 from private.hangout_feature_gate where singleton for share;
 if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 select array_agg(s order by s) into subjects from (select distinct unnest(array[actor_id,host_id]) s) ids;
 foreach subject in array subjects loop
  perform 1 from public.accounts where id=subject for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 end loop;
 foreach subject in array subjects loop
  perform 1 from private.pilot_account_admission where account_id=subject for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 end loop;
 foreach subject in array subjects loop
  perform 1 from auth.users where id=subject for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 end loop;
 foreach subject in array subjects loop
  select m.university_id into campus from public.university_memberships m where m.user_id=subject for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  memberships:=memberships||jsonb_build_object(subject::text,campus);
 end loop;
 if campus_id is null then campus_id:=(memberships->>actor_id::text)::uuid; end if;
 for campus in select distinct value::uuid from jsonb_each_text(memberships) order by value::uuid loop
  perform 1 from public.universities c where c.id=campus for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 end loop;
 foreach subject in array subjects loop
  select p.primary_photo_path into photo from public.profiles p where p.user_id=subject for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  if photo is null then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  photos:=photos||jsonb_build_object(subject::text,photo);
 end loop;
 for subject,photo in select key::uuid,value from jsonb_each_text(photos) order by value,key::uuid loop
  select o.id into object_id from storage.objects o where o.bucket_id='profile-photos' and o.name=photo and o.owner_id=subject::text for share;
  if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  objects:=objects||jsonb_build_object(subject::text,object_id);
 end loop;
 locked_subject_bindings:='[]';
 foreach subject in array subjects loop
  binding:=jsonb_build_object('subject_id',subject,'membership_campus_id',memberships->>subject::text,
   'primary_photo_path',photos->>subject::text,'storage_object_id',objects->>subject::text);
  locked_subject_bindings:=locked_subject_bindings||jsonb_build_array(binding);
 end loop;
 -- All waits finished. Bind every current predicate to the actual locked tuple,
 -- never a fresh EXISTS that could accept an unlocked replacement row.
 foreach subject in array subjects loop
  if not private.ready_subject_campus(subject,campus_id)
   or (memberships->>subject::text)::uuid is distinct from campus_id
   or not exists(select 1 from public.university_memberships m where m.user_id=subject and m.university_id=(memberships->>subject::text)::uuid)
   or not exists(select 1 from public.profiles p where p.user_id=subject and p.primary_photo_path=photos->>subject::text)
   or not exists(select 1 from storage.objects o where o.id=(objects->>subject::text)::uuid and o.bucket_id='profile-photos' and o.name=photos->>subject::text and o.owner_id=subject::text) then
   raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 end loop;
 -- Original lower state boundary follows the complete identity phases. Source
 -- parent UPDATE prevents new FK-bound state rows from appearing behind us.
 if source_row.id is not null then
  perform 1 from public.hangout_participants p where p.hangout_id=source_row.id and p.account_id=actor_id for update;
  if not found and p_operation='leave_hangout' then
   raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  if p_operation in ('edit_hangout','set_hangout_joining') and actor_id<>host_id then
   perform 1 from private.hangout_cohosts c where c.hangout_id=source_row.id and c.account_id=actor_id for share;
   if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  end if;
 end if;
 perform private.pilot_require_ordinary_lifecycle(p_operation,coalesce(p_hangout_id,prior_hangout_id));
 return next;
end; $function$

CREATE OR REPLACE FUNCTION public.edit_hangout(p_hangout_id uuid, p_expected_revision bigint, p_title text, p_starts_at timestamp with time zone, p_public_place text, p_public_latitude double precision, p_public_longitude double precision, p_description text DEFAULT NULL::text, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_campus_zone text DEFAULT NULL::text, p_private_instructions text DEFAULT NULL::text, p_visibility text DEFAULT 'campus'::text, p_location_precision text DEFAULT 'approximate_area'::text, p_eligibility jsonb DEFAULT NULL::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence record; h public.hangouts; next_revision bigint; normalized_private text; old_private text; material boolean;
begin
 select * into evidence from private.pilot_lock_ordinary_lifecycle('edit_hangout',p_hangout_id);
 h:=evidence.source_row;
 perform private.pilot_require_ordinary_lifecycle('edit_hangout',p_hangout_id);
 if (h.host_id<>auth.uid() and not private.effective_hangout_cohost(h.id,auth.uid())) or h.status<>'published' then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.check_hangout_revision(h,p_expected_revision);
 perform private.validate_hangout_input(p_title,p_starts_at,p_public_place,p_public_latitude,p_public_longitude,p_description,p_ends_at,p_campus_zone,p_visibility,p_location_precision,p_eligibility);
 perform private.validate_hangout_instructions(p_private_instructions);
 if p_starts_at is distinct from h.starts_at and (p_starts_at<clock_timestamp() or p_starts_at>clock_timestamp()+interval '366 days') then
   raise exception 'Invalid Hangout input' using errcode='22023'; end if;
 normalized_private=nullif(private.profile_trim(p_private_instructions),'');
 select instructions into old_private from public.hangout_private_locations where hangout_id=h.id;
 perform private.pilot_require_ordinary_lifecycle('edit_hangout',p_hangout_id);
 update public.hangouts set title=private.profile_trim(p_title),starts_at=p_starts_at,public_place=private.profile_trim(p_public_place),public_latitude=p_public_latitude,public_longitude=p_public_longitude,description=nullif(private.profile_trim(p_description),''),ends_at=p_ends_at,campus_zone=nullif(private.profile_trim(p_campus_zone),''),revision=revision+1,updated_at=clock_timestamp() where id=h.id returning revision into next_revision;
 if normalized_private is null then delete from public.hangout_private_locations where hangout_id=h.id;
 else insert into public.hangout_private_locations(hangout_id,instructions) values(h.id,normalized_private)
  on conflict(hangout_id) do update set instructions=excluded.instructions,updated_at=clock_timestamp(); end if;
 material:=row(h.title,h.starts_at,h.public_place,h.public_latitude,h.public_longitude,h.description,h.ends_at,h.campus_zone,old_private)
  is distinct from row(private.profile_trim(p_title),p_starts_at,private.profile_trim(p_public_place),p_public_latitude,p_public_longitude,
   nullif(private.profile_trim(p_description),''),p_ends_at,nullif(private.profile_trim(p_campus_zone),''),normalized_private);
 if material then perform private.notification_emit_hangout(gen_random_uuid(),h.id,auth.uid(),'hangout_edited'); end if;
 return next_revision;
end; $function$

CREATE OR REPLACE FUNCTION public.promote_hangout_cohost(p_hangout_id uuid, p_account_id uuid, p_expected_revision bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.hangouts; next_revision bigint;
begin
  perform private.social_hangout_mutation_lock();
  h := private.lock_hangout(p_hangout_id);
  if p_account_id is not null and p_account_id <> h.host_id then
    perform private.safety_lock_hangout_evidence(p_account_id, h.university_id);
  end if;
  if h.host_id <> auth.uid() or h.status <> 'published' or p_account_id is null
    or p_account_id = h.host_id or not exists(
      select 1 from public.hangout_participants p where p.hangout_id = h.id
        and p.account_id = p_account_id and p.state = 'joined')
    or not private.ready_subject_campus(p_account_id, h.university_id)
    or private.safety_pair_blocked(h.host_id, p_account_id)
    or exists(select 1 from private.hangout_cohosts c where c.hangout_id = h.id
      and c.account_id = p_account_id) then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  perform private.check_hangout_revision(h, p_expected_revision);
  insert into private.hangout_cohosts(hangout_id, account_id) values(h.id, p_account_id);
  update public.hangouts set revision = revision + 1, updated_at = clock_timestamp()
    where id = h.id returning revision into next_revision;
  return next_revision;
end;
$function$

