CREATE OR REPLACE FUNCTION public.remove_hangout_participant(p_hangout_id uuid, p_account_id uuid, p_expected_revision bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h public.hangouts; next_revision bigint; target_state text;
begin
  perform private.social_hangout_mutation_lock();
  h := private.lock_hangout(p_hangout_id);
  if p_account_id is null or p_account_id = h.host_id
    or (h.host_id <> auth.uid() and not private.effective_hangout_cohost(h.id, auth.uid()))
    or (h.host_id <> auth.uid() and h.status <> 'published') then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  perform private.check_hangout_revision(h, p_expected_revision);
  select state into target_state from public.hangout_participants p
    where p.hangout_id = h.id and p.account_id = p_account_id;
  if target_state not in ('joined','left') or target_state is null then
    raise exception 'Hangout operation not permitted' using errcode = '42501';
  end if;
  if h.host_id <> auth.uid() then
    perform private.safety_lock_hangout_evidence(p_account_id, h.university_id);
    if target_state <> 'joined'
      or not private.ready_subject_campus(p_account_id, h.university_id)
      or exists(select 1 from private.hangout_cohosts c
        where c.hangout_id = h.id and c.account_id = p_account_id)
      or private.safety_pair_blocked(auth.uid(), p_account_id)
      or not private.effective_hangout_cohost(h.id, auth.uid()) then
      raise exception 'Hangout operation not permitted' using errcode = '42501';
    end if;
  end if;
  perform private.safety_record_joined_overlap(h.id, p_account_id);
  update public.hangout_participants set state = 'removed',
    removed_at = clock_timestamp(), updated_at = clock_timestamp()
    where hangout_id = h.id and account_id = p_account_id and state in ('joined','left');
  if not found then raise exception 'Hangout operation not permitted' using errcode = '42501'; end if;
  update public.hangouts set revision = revision + 1,
    updated_at = case when status = 'cancelled' then updated_at else clock_timestamp() end
    where id = h.id returning revision into next_revision;
  return next_revision;
end;
$function$

CREATE OR REPLACE FUNCTION private.pilot_lock_management(p_actor uuid, p_target uuid, p_policy_key text, p_manager_write boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare subject uuid;
begin
 perform private.pilot_evidence_write_lock();
 if p_policy_key='availability' then perform 1 from private.pilot_availability where singleton for update;
 else perform 1 from private.pilot_availability where singleton for share; end if;
 perform 1 from private.pilot_capabilities where key<>coalesce(p_policy_key,'') order by key for share;
 if p_policy_key is not null and p_policy_key<>'availability' then perform 1 from private.pilot_capabilities where key=p_policy_key for update; end if;
 for subject in select distinct v from unnest(array[p_actor,p_target]) v where v is not null order by v loop
  perform 1 from public.accounts where id=subject for share;
 end loop;
 for subject in select distinct v from unnest(array[p_actor,p_target]) v where v is not null order by v loop
  if p_manager_write and subject=p_target then perform 1 from private.pilot_admission_managers where account_id=subject for update;
  else perform 1 from private.pilot_admission_managers where account_id=subject for share; end if;
 end loop;
 for subject in select distinct v from unnest(array[p_actor,p_target]) v where v is not null order by v loop
  if not p_manager_write and subject=p_target and p_policy_key is null then perform 1 from private.pilot_account_admission where account_id=subject for update;
  else perform 1 from private.pilot_account_admission where account_id=subject for share; end if;
 end loop;
end; $function$

CREATE OR REPLACE FUNCTION private.pilot_require_manager()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
 if actor is null or not exists(select 1 from public.accounts where id=actor and status='active')
  or not exists(select 1 from private.pilot_admission_managers where account_id=actor and state='active') then
  raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 return actor;
end; $function$

CREATE OR REPLACE FUNCTION private.set_pilot_manager_fixture(p_account_id uuid, p_state text, p_expected_revision bigint, p_reason text, p_request_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare original_role text:=current_setting('role',true); reason text:=private.profile_trim(p_reason); old private.pilot_admission_managers%rowtype; next_revision bigint;
begin
 if session_user<>'postgres' or original_role not in ('none','postgres') then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 perform private.pilot_lock_management(null,p_account_id,null,true);
 if p_account_id is null or p_state is null or p_state not in ('active','revoked') or p_expected_revision is null or p_expected_revision<0
  or reason is null or char_length(reason) not between 1 and 2000 or p_request_id is null
  or not exists(select 1 from public.accounts where id=p_account_id) then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 select * into old from private.pilot_admission_managers where account_id=p_account_id;
 if coalesce(old.revision,0)<>p_expected_revision then raise exception 'Pilot management unavailable' using errcode='42501'; end if;
 next_revision:=case when old.state=p_state then old.revision else coalesce(old.revision,0)+1 end;
 if old.account_id is null then insert into private.pilot_admission_managers(account_id,state,revision) values(p_account_id,p_state,next_revision);
 elsif old.state<>p_state then update private.pilot_admission_managers set state=p_state,revision=next_revision,updated_at=clock_timestamp() where account_id=p_account_id; end if;
 insert into private.pilot_manager_audit(account_id,executor_session_user,executor_original_role,executor_backend_pid,previous_state,new_state,previous_revision,new_revision,reason,request_id)
 values(p_account_id,session_user,original_role,pg_backend_pid(),old.state,p_state,coalesce(old.revision,0),next_revision,reason,p_request_id);
 return next_revision;
end; $function$

CREATE OR REPLACE FUNCTION private.pilot_lock_owner_evidence(subject uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare campus uuid;
begin
 perform private.pilot_evidence_lock();
 perform 1 from private.pilot_availability where singleton for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 perform 1 from private.pilot_capabilities where key='onboarding' for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 -- One involved account, hence trivially sorted UUID order.
 perform 1 from public.accounts where id=subject for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 perform 1 from private.pilot_account_admission where account_id=subject for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 perform 1 from auth.users where id=subject for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 select university_id into campus from public.university_memberships where user_id=subject for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 perform 1 from public.universities where id=campus for share;
 if not found then raise exception 'Owner operation unavailable' using errcode='42501'; end if;
 -- This separate volatile statement receives a fresh READ COMMITTED snapshot.
 if subject is null or not private.pilot_owner_subject_eligible(subject)
  or not exists(select 1 from public.university_memberships where user_id=subject and university_id=campus) then
  raise exception 'Owner operation unavailable' using errcode='42501'; end if;
end; $function$

CREATE OR REPLACE FUNCTION public.set_hangout_joining(p_hangout_id uuid, p_expected_revision bigint, p_joining_state text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence record; h public.hangouts; next_revision bigint;
begin
 select * into evidence from private.pilot_lock_ordinary_lifecycle('set_hangout_joining',p_hangout_id);
 h:=evidence.source_row;
 perform private.pilot_require_ordinary_lifecycle('set_hangout_joining',p_hangout_id);
 if (h.host_id<>auth.uid() and not private.effective_hangout_cohost(h.id,auth.uid())) or h.status<>'published' then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 perform private.check_hangout_revision(h,p_expected_revision);
 if p_joining_state is null or p_joining_state not in ('open','closed') then raise exception 'Invalid joining state' using errcode='22023'; end if;
 perform private.pilot_require_ordinary_lifecycle('set_hangout_joining',p_hangout_id);
 update public.hangouts set joining_state=p_joining_state,revision=revision+1,updated_at=clock_timestamp() where id=h.id returning revision into next_revision;
 return next_revision;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_active_photo_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target storage.objects%rowtype; subject uuid; original_role text:=current_setting('role',true);
begin
 target:=case when tg_op='DELETE' then old else new end;
 if target.bucket_id='profile-photos' then
  if original_role='authenticated' then
   subject:=auth.uid();
   if subject is null or target.owner_id is distinct from subject::text then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
  elsif original_role='service_role' then
   -- Real Storage first checks client permission separately, then persists as
   -- supabase_storage_admin/service_role with auth.uid null. Guard that final
   -- row through commit using its server-assigned owner; no service RPC grant.
   if tg_op<>'INSERT' or session_user<>'supabase_storage_admin' or target.owner_id is null
    or target.owner_id !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
   subject:=target.owner_id::uuid;
   -- Storage finalizes via UPSERT even for a create request. Never let its
   -- privileged final insert overwrite an already committed immutable name.
   if exists(select 1 from storage.objects o where o.bucket_id=target.bucket_id and o.name=target.name) then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
  end if;
  if original_role in ('authenticated','service_role') then
   if target.name !~ ('^'||subject::text||'/[a-f0-9-]+\.(jpg|png|webp)$') then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
   perform private.pilot_lock_owner_evidence(subject);
  end if;
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.set_safety_block(p_account_id uuid, p_blocked boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); target uuid; hangout_row public.hangouts%rowtype; effect text;
begin
  perform private.social_hangout_mutation_lock();
  if actor is null or p_account_id is null or p_account_id=actor or p_blocked is null
      or not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501';
  end if;
  perform private.friendship_lock_pair(actor,p_account_id);
  -- A fresh READ COMMITTED statement discovers the full currently shared set
  -- after every preceding mutation. Sorted parents precede gate/evidence rows.
  for target in
    select x.hangout_id from public.hangout_participants x
    join public.hangout_participants y on y.hangout_id=x.hangout_id
    where x.account_id=actor and y.account_id=p_account_id
      and x.state='joined' and y.state='joined' order by x.hangout_id
  loop
    perform 1 from public.hangouts where id=target for update;
  end loop;
  perform 1 from private.safety_feature_gate where singleton for share;
  if not private.safety_enabled() or not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501';
  end if;
  perform 1 from public.accounts where id=actor for share;
  if not private.people_active_owner() then
    raise exception 'Safety operation unavailable' using errcode='42501'; end if;
  if p_blocked then
    if not private.safety_peer_evidence(actor,p_account_id) then
      perform private.safety_lock_visible_evidence(actor,p_account_id);
    end if;
    if not (private.safety_peer_evidence(actor,p_account_id)
      or (private.pilot_capability_enabled('people') and private.people_enabled() and private.people_ready_campus() is not null
         and private.people_visible(p_account_id,private.people_ready_campus()))) then
      raise exception 'Safety operation unavailable' using errcode='42501';
    end if;
    insert into private.people_blocks(blocker_id,blocked_id)
      values(actor,p_account_id) on conflict do nothing;
    -- Recheck the entire affected set after lock waits. The shared lock keeps
    -- membership stable through commit; this also repairs old-block retries.
    for hangout_row in select hh.* from public.hangouts hh
      join public.hangout_participants x on x.hangout_id=hh.id
        and x.account_id=actor and x.state='joined'
      join public.hangout_participants y on y.hangout_id=hh.id
        and y.account_id=p_account_id and y.state='joined'
      order by hh.id
    loop
      perform private.safety_record_joined_overlap(hangout_row.id,actor);
      perform private.safety_record_joined_overlap(hangout_row.id,p_account_id);
      effect:=case when hangout_row.host_id=actor then 'removed' else 'left' end;
      update public.hangout_participants set state=effect,
        left_at=case when effect='left' then clock_timestamp() else left_at end,
        removed_at=case when effect='removed' then clock_timestamp() else removed_at end,
        updated_at=clock_timestamp()
      where hangout_id=hangout_row.id and account_id=case when effect='removed' then p_account_id else actor end
        and state='joined';
    end loop;
    delete from private.friendships f where f.low_id=least(actor,p_account_id)
      and f.high_id=greatest(actor,p_account_id);
    update private.dm_pairs d set state='blocked' where d.low_id=least(actor,p_account_id)
      and d.high_id=greatest(actor,p_account_id) and d.state in('pending','accepted');
  else
    delete from private.people_blocks b where b.blocker_id=actor and b.blocked_id=p_account_id;
  end if;
  return p_blocked;
end; $function$

CREATE OR REPLACE FUNCTION public.submit_safety_report(p_request_id uuid, p_target_mode text, p_target_id uuid, p_category text, p_narrative text DEFAULT NULL::text)
 RETURNS TABLE(receipt_id uuid, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=auth.uid(); normalized_category text; normalized_narrative text;
  input_fingerprint text; prior private.safety_report_requests%rowtype;
  retained boolean; target_type text; resolved_target uuid;
  provenance text; provenance_ref uuid; campus uuid;
  parent public.hangouts%rowtype; saved_id uuid; saved_at timestamptz;
begin
  perform private.social_hangout_mutation_lock();
  -- Shape validation never probes the target. Invalid UUID text is rejected by
  -- PostgREST before this function with its ordinary parameter error.
  normalized_category:=pg_catalog.lower(private.profile_trim(p_category));
  normalized_narrative:=nullif(private.profile_trim(p_narrative),'');
  if actor is null or p_request_id is null or p_target_id is null
    or p_target_mode is null or p_target_mode not in ('user','hangout','hangout_host')
    or normalized_category is null or normalized_category not in
      ('harassment','safety concern','impersonation','spam/commercial promotion','other')
    or (normalized_narrative is not null and pg_catalog.length(normalized_narrative)>2000)
    or (normalized_category='other' and normalized_narrative is null) then
    raise exception 'Safety report unavailable' using errcode='42501';
  end if;
  input_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_target_mode,p_target_id,normalized_category,normalized_narrative)::text);

  -- The shared transaction lock serializes every caller, including retries.
  -- A replay only reads its own ledger and never resolves its target again.
  select * into prior from private.safety_report_requests r
    where r.reporter_id=actor and r.request_id=p_request_id;
  if found then
    perform 1 from private.safety_feature_gate where singleton for share;
    perform 1 from public.accounts where id=actor for share;
    if not private.safety_enabled() or not private.people_active_owner() then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    if prior.input_fingerprint<>input_fingerprint then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    return query select r.id,r.submitted_at from private.safety_reports r
      where r.id=prior.report_id and r.reporter_id=actor;
    return;
  end if;

  -- A nonlocking hint chooses the path before any lower gate/account lock.
  -- Its authority is checked again after those locks are held.
  if p_target_mode='user' then
    retained:=private.safety_peer_evidence(actor,p_target_id);
  else
    retained:=exists(select 1 from public.hangout_participants p
      where p.hangout_id=p_target_id and p.account_id=actor);
  end if;
  if not retained then
    if p_target_mode='hangout_host' then
      raise exception 'Safety report unavailable' using errcode='42501';
    elsif p_target_mode='user' then
      perform private.friendship_lock_pair(actor,p_target_id);
    else
      select * into parent from public.hangouts h where h.id=p_target_id for update;
      if not found then raise exception 'Safety report unavailable' using errcode='42501'; end if;
    end if;
  end if;

  perform 1 from private.safety_feature_gate where singleton for share;
  if not retained then
    if p_target_mode='user' then
      perform private.safety_lock_visible_evidence(actor,p_target_id);
    else
      perform 1 from private.hangout_feature_gate where singleton for share;
      perform private.safety_lock_hangout_evidence(actor,parent.university_id);
    end if;
  else
    perform 1 from public.accounts where id=actor for share;
  end if;

  -- Each of these checks is a fresh READ COMMITTED statement after all waits.
  if not private.safety_enabled() or not private.people_active_owner() then
    raise exception 'Safety report unavailable' using errcode='42501'; end if;
  if retained then
    if p_target_mode='user' then
      select kind,ref_id into provenance,provenance_ref
        from private.safety_report_peer_source(actor,p_target_id);
      if not found or not private.safety_peer_evidence(actor,p_target_id) then
        raise exception 'Safety report unavailable' using errcode='42501'; end if;
      target_type:='user'; resolved_target:=p_target_id;
    else
      select h.host_id into resolved_target from public.hangout_participants p
        join public.hangouts h on h.id=p.hangout_id
        where p.hangout_id=p_target_id and p.account_id=actor;
      if not found then raise exception 'Safety report unavailable' using errcode='42501'; end if;
      if p_target_mode='hangout_host' then
        target_type:='user'; provenance:='retained_host';
        provenance_ref:=p_target_id;
      else
        target_type:='hangout'; resolved_target:=p_target_id;
        provenance:='retained_hangout'; provenance_ref:=p_target_id;
      end if;
    end if;
  elsif p_target_mode='user' then
    campus:=private.people_ready_campus();
    if not private.pilot_capability_enabled('people') or not private.people_enabled() or campus is null
      or not private.people_visible(p_target_id,campus) then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    target_type:='user'; resolved_target:=p_target_id;
    provenance:='current_people'; provenance_ref:=p_target_id;
  else
    if not private.hangouts_enabled() or not private.can_read_hangout(p_target_id,false) then
      raise exception 'Safety report unavailable' using errcode='42501'; end if;
    target_type:='hangout'; resolved_target:=p_target_id;
    provenance:='current_hangout'; provenance_ref:=p_target_id;
  end if;
  if target_type='user' and resolved_target=actor then
    raise exception 'Safety report unavailable' using errcode='42501'; end if;

  -- Inclusive lower edge: a row at exactly now-1 hour still consumes a slot.
  -- The clock is sampled after contention and after final authorization.
  saved_at:=clock_timestamp();
  if (select count(*) from private.safety_reports r where r.reporter_id=actor
      and r.submitted_at between saved_at-interval '1 hour' and saved_at)>=5 then
    raise exception 'Safety report unavailable' using errcode='42501'; end if;
  insert into private.safety_reports(reporter_id,target_type,target_id,category,narrative,
    provenance_kind,provenance_ref_id,submitted_at)
    values(actor,target_type,resolved_target,normalized_category,normalized_narrative,
      provenance,provenance_ref,saved_at) returning id into saved_id;
  insert into private.safety_report_requests(reporter_id,request_id,input_fingerprint,report_id)
    values(actor,p_request_id,input_fingerprint,saved_id);
  return query select saved_id,saved_at;
end; $function$

CREATE OR REPLACE FUNCTION private.moderation_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
  perform pg_advisory_xact_lock(17017,1);
  if current_setting('transaction_isolation')<>'read committed' or actor is null then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  perform 1 from private.moderation_feature_gate where singleton for share;
  if not found then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  -- SHARE blocks status/deletion changes but is compatible with the existing
  -- report intake actor SHARE after its Hangout parent lock.
  perform 1 from public.accounts where id=actor for share;
  if not found then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  perform 1 from public.platform_roles where user_id=actor for share;
  if not found then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  if not exists(select 1 from private.moderation_feature_gate where singleton and enabled)
    or not exists(select 1 from public.accounts where id=actor and status='active')
    or not exists(select 1 from public.platform_roles where user_id=actor and role in ('moderator','admin')) then
    raise exception 'Moderation unavailable' using errcode='42501'; end if;
  return actor;
end; $function$

CREATE OR REPLACE FUNCTION private.pilot_require_ordinary_lifecycle(p_operation text, p_hangout_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); h public.hangouts;
begin
 if p_operation is null or p_operation not in ('create_hangout','edit_hangout','cancel_hangout','join_hangout','leave_hangout','set_hangout_joining')
  or actor is null or not private.pilot_capability_enabled('hangouts') or not private.hangouts_enabled()
  or private.ready_campus() is null then
  raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if p_hangout_id is null then
  if p_operation<>'create_hangout' then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
  return;
 end if;
 select * into h from public.hangouts where id=p_hangout_id;
 if not found then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if not private.can_read_hangout(h.id) then raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
 if p_operation='create_hangout' and h.host_id<>actor
  or p_operation='cancel_hangout' and (h.status<>'published' or h.host_id<>actor)
  or p_operation in ('edit_hangout','set_hangout_joining') and (h.status<>'published' or (h.host_id<>actor and not private.effective_hangout_cohost(h.id,actor)))
  or p_operation='join_hangout' and (h.status<>'published' or h.joining_state<>'open'
    or exists(select 1 from public.hangout_participants p where p.hangout_id=h.id and p.state='joined' and p.account_id<>actor and private.safety_pair_blocked(actor,p.account_id))
    or exists(select 1 from public.hangout_participants p where p.hangout_id=h.id and p.account_id=actor and p.state='removed'))
  or p_operation='leave_hangout' and (h.host_id=actor or not exists(select 1 from public.hangout_participants p where p.hangout_id=h.id and p.account_id=actor and p.state='joined')) then
  raise exception 'Hangout operation not permitted' using errcode='42501'; end if;
end; $function$
